  e.preventDefault();
  const text = messageInput.value.trim();
  if (!text) return;

  try {
    await fetch(`${API_BASE}/messages`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text }),
    });
    messageInput.value = '';
  } catch (err) {
    console.error('Failed to post message:', err);
  }
});

// Initialize
loadMessages();
connectSSE();
