    }
  }
  console.log(`Broadcast complete. Sent to ${sentCount}/${sseClients.length} clients.`);
}

// ---- Start Server ----

async function start() {
  await initDatabase();
  app.listen(PORT, () => {
    console.log(`Backend server running on http://localhost:${PORT}`);
  });
