import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import fs from 'fs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = 3000;

// Middleware
app.use(cors());
app.use(express.json());

// Ensure data directory exists for PGLite persistence
const dataDir = join(__dirname, 'pglite-data');
if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir, { recursive: true });
}

// Initialize PGLite with filesystem persistence
const db = new PGlite({
  dataDir: `file://${dataDir}`,
});

// SSE clients registry - store both the write function and the response for flushing
const sseClients = [];

// ---- Database Initialization ----

async function initDatabase() {
  await db.exec(`
    CREATE TABLE IF NOT EXISTS messages (
      id SERIAL PRIMARY KEY,
      text TEXT NOT NULL,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
    );
  `);
  console.log('Database initialized.');
}

// ---- API Routes ----

// GET /api/messages - Fetch all messages
app.get('/api/messages', async (req, res) => {
  try {
    const result = await db.query(
      'SELECT id, text, created_at FROM messages ORDER BY created_at ASC'
    );
    const messages = result.rows.map((row) => ({
      id: row.id,
      text: row.text,
      created_at: row.created_at,
    }));
    res.json(messages);
  } catch (err) {
    console.error('Error fetching messages:', err);
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// POST /api/messages - Insert a new message and broadcast via SSE
app.post('/api/messages', async (req, res) => {
  try {
    const { text } = req.body;
    if (!text || typeof text !== 'string') {
      return res.status(400).json({ error: 'Text is required' });
    }

    const result = await db.query(
      "INSERT INTO messages (text) VALUES ($1) RETURNING id, text, created_at",
      [text]
    );
    const message = {
      id: result.rows[0].id,
      text: result.rows[0].text,
      created_at: result.rows[0].created_at,
    };

    // Broadcast to all SSE clients
    broadcast(message);

    res.status(201).json(message);
  } catch (err) {
    console.error('Error inserting message:', err);
    res.status(500).json({ error: 'Failed to insert message' });
  }
});

// GET /api/stream - SSE endpoint for real-time updates
app.get('/api/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering

  // Flush headers immediately
  res.flushHeaders();

  const client = { write: res.write.bind(res), res };
  sseClients.push(client);
  console.log(`SSE client connected. Total clients: ${sseClients.length}`);

  req.on('close', () => {
    const index = sseClients.indexOf(client);
    if (index !== -1) {
      sseClients.splice(index, 1);
    }
    console.log(`SSE client disconnected. Total clients: ${sseClients.length}`);
  });
});

// Broadcast function
function broadcast(message) {
  const data = JSON.stringify(message);
  const payload = `data: ${data}\n\n`;
  let sentCount = 0;
  for (const client of sseClients) {
    try {
      const result = client.write(payload);
      console.log(`SSE broadcast to client: write returned ${result}`);
      if (result === true) sentCount++;
    } catch (err) {
      console.error('SSE broadcast error:', err.message);
    }
  }
  console.log(`Broadcast complete. Sent to ${sentCount}/${sseClients.length} clients.`);
}

// ---- Start Server ----

async function start() {
  await initDatabase();
  app.listen(PORT, () => {
    console.log(`Backend server running on http://localhost:${PORT}`);
  });
}

start().catch((err) => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

import { defineConfig } from 'vite';

export default defineConfig({
  root: 'frontend',
  server: {
    port: 5173,
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true,
        ws: false,
        configure: (proxy) => {
          // Don't proxy SSE connections - they need to be direct
          proxy.on('proxyReq', (proxyReq, req) => {
            if (req.url === '/api/stream') {
              // Let the SSE connection pass through as-is
            }
          });
        },
      },
    },
  },
});

const messageList = document.getElementById('message-list');
const messageForm = document.getElementById('message-form');
const messageInput = document.getElementById('message-input');

// API base URL - in dev, connect directly to backend for SSE (Vite proxy doesn't handle SSE well)
// In production, all requests go through the same origin
const isDev = window.location.hostname === 'localhost' && window.location.port !== '3000';
const API_BASE = isDev ? 'http://localhost:3000/api' : '/api';

// Format timestamp for display
function formatTime(isoString) {
  const date = new Date(isoString);
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

// Create a message DOM element
function createMessageElement(message) {
  const div = document.createElement('div');
  div.className = 'message';
  div.innerHTML = `
    <p class="message-text">${escapeHtml(message.text)}</p>
    <span class="message-time">${formatTime(message.created_at)}</span>
  `;
  return div;
}

// Escape HTML to prevent XSS
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// Fetch and render historical messages
async function loadMessages() {
  try {
    const res = await fetch(`${API_BASE}/messages`);
    const messages = await res.json();
    messageList.innerHTML = '';
    for (const msg of messages) {
      messageList.appendChild(createMessageElement(msg));
    }
  } catch (err) {
    console.error('Failed to load messages:', err);
  }
}

// Connect to SSE stream for real-time updates
function connectSSE() {
  const eventSource = new EventSource(`${API_BASE}/stream`);

  eventSource.addEventListener('message', (event) => {
    const message = JSON.parse(event.data);
    const el = createMessageElement(message);
    messageList.appendChild(el);
    // Scroll to the bottom
    window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
  });

  eventSource.onerror = (err) => {
    console.error('SSE connection error:', err);
    eventSource.close();
    // Reconnect after a delay
    setTimeout(connectSSE, 3000);
  };
}

// Handle form submission
messageForm.addEventListener('submit', async (e) => {
  e.preventDefault();
  const text = messageInput.value.trim();
  if (!text) return;

  try {
    await fetch(`${API_BASE}/messages`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text }),
    });
    messageInput.value = '';
  } catch (err) {
    console.error('Failed to post message:', err);
  }
});

// Initialize
loadMessages();
connectSSE();

